{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_text",
        "considerations_heading",
        "location_card",
        "amenities_card",
        "breakfast_card",
        "budget_card",
        "reviews_card",
        "booking_flexibility_card",
        "divider_1",
        "quick_actions_heading",
        "explore_hotels_button",
        "disney_guide_button",
        "universal_info_button",
        "sources_heading",
        "visitorlando_source_button",
        "disneyworld_source_button",
        "universalorlando_source_button"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Orlando Family Hotel Planning: Summer Stay Essentials",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Planning a family trip to Orlando for two adults and two children (ages 6 and 9) from July 20-27, 2024, requires careful consideration to ensure a memorable and comfortable stay. Focusing on hotels with a pool and complimentary breakfast, here are the key factors to evaluate for your family-friendly accommodation."
      },
      "children": []
    },
    "considerations_heading": {
      "type": "Text",
      "props": {
        "text": "Key Hotel Booking Considerations for Orlando Families",
        "variant": "h3"
      },
      "children": []
    },
    "location_card": {
      "type": "Card",
      "props": {},
      "children": [
        "location_header_stack",
        "location_text_stack"
      ]
    },
    "location_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "location_icon",
        "location_title"
      ]
    },
    "location_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/geo-alt.svg"
      },
      "children": []
    },
    "location_title": {
      "type": "Text",
      "props": {
        "text": "Location & Theme Park Access",
        "variant": "h3"
      },
      "children": []
    },
    "location_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "location_proximity",
        "location_transportation",
        "location_walkability"
      ]
    },
    "location_proximity": {
      "type": "Text",
      "props": {
        "text": "Proximity: Decide on your primary theme park focus (Walt Disney World, Universal Orlando Resort, or SeaWorld Orlando) and choose a hotel that minimizes travel time."
      },
      "children": []
    },
    "location_transportation": {
      "type": "Text",
      "props": {
        "text": "Transportation: Look for hotels offering complimentary shuttle services to the parks to save on parking fees and reduce driving hassle."
      },
      "children": []
    },
    "location_walkability": {
      "type": "Text",
      "props": {
        "text": "Walkability: Some areas around Universal CityWalk or Disney Springs offer walkability to dining and entertainment, which can be a bonus."
      },
      "children": []
    },
    "amenities_card": {
      "type": "Card",
      "props": {},
      "children": [
        "amenities_header_stack",
        "amenities_text_stack"
      ]
    },
    "amenities_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "amenities_icon",
        "amenities_title"
      ]
    },
    "amenities_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/person-fill-gear.svg"
      },
      "children": []
    },
    "amenities_title": {
      "type": "Text",
      "props": {
        "text": "Family-Focused Amenities",
        "variant": "h3"
      },
      "children": []
    },
    "amenities_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "amenities_pool",
        "amenities_room",
        "amenities_onsite"
      ]
    },
    "amenities_pool": {
      "type": "Text",
      "props": {
        "text": "Pool Features: Beyond a basic pool, seek out properties with splash pads, water slides, lazy rivers, or zero-entry pools suitable for young children."
      },
      "children": []
    },
    "amenities_room": {
      "type": "Text",
      "props": {
        "text": "Room Configuration: Consider suites, connecting rooms, or rooms with pull-out sofas to ensure comfortable sleeping arrangements and space for everyone. Kitchenettes can also be very helpful for snacks and light meals."
      },
      "children": []
    },
    "amenities_onsite": {
      "type": "Text",
      "props": {
        "text": "On-site Activities: Some resorts offer kids' clubs, playgrounds, game rooms, or evening entertainment that can provide downtime from the parks."
      },
      "children": []
    },
    "breakfast_card": {
      "type": "Card",
      "props": {},
      "children": [
        "breakfast_header_stack",
        "breakfast_text_stack"
      ]
    },
    "breakfast_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "breakfast_icon",
        "breakfast_title"
      ]
    },
    "breakfast_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/egg-fried.svg"
      },
      "children": []
    },
    "breakfast_title": {
      "type": "Text",
      "props": {
        "text": "Complimentary Breakfast Details",
        "variant": "h3"
      },
      "children": []
    },
    "breakfast_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "breakfast_type",
        "breakfast_dining",
        "breakfast_hours"
      ]
    },
    "breakfast_type": {
      "type": "Text",
      "props": {
        "text": "Type & Quality: Verify if it's a continental spread or a full hot breakfast. Ensure there are options appealing to both adults and children, such as fruit, pastries, eggs, and cereal."
      },
      "children": []
    },
    "breakfast_dining": {
      "type": "Text",
      "props": {
        "text": "Dining Space: Check if there's ample seating, especially during peak morning hours, to avoid long waits before heading to the parks."
      },
      "children": []
    },
    "breakfast_hours": {
      "type": "Text",
      "props": {
        "text": "Hours: Confirm breakfast hours align with your early park entry plans."
      },
      "children": []
    },
    "budget_card": {
      "type": "Card",
      "props": {},
      "children": [
        "budget_header_stack",
        "budget_text_stack"
      ]
    },
    "budget_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "budget_icon",
        "budget_title"
      ]
    },
    "budget_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/currency-dollar.svg"
      },
      "children": []
    },
    "budget_title": {
      "type": "Text",
      "props": {
        "text": "Budget & Value Additions",
        "variant": "h3"
      },
      "children": []
    },
    "budget_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "budget_fees",
        "budget_inclusions",
        "budget_loyalty"
      ]
    },
    "budget_fees": {
      "type": "Text",
      "props": {
        "text": "Hidden Fees: Always factor in resort fees, parking charges, and taxes, which are common in Orlando and can significantly increase the total cost."
      },
      "children": []
    },
    "budget_inclusions": {
      "type": "Text",
      "props": {
        "text": "Value Inclusions: Some hotels offer additional perks like free parking, evening receptions, or discounts on local attractions that add value to your stay."
      },
      "children": []
    },
    "budget_loyalty": {
      "type": "Text",
      "props": {
        "text": "Loyalty Programs: If you're part of a hotel loyalty program, check for member benefits or points redemption opportunities."
      },
      "children": []
    },
    "reviews_card": {
      "type": "Card",
      "props": {},
      "children": [
        "reviews_header_stack",
        "reviews_text_stack"
      ]
    },
    "reviews_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "reviews_icon",
        "reviews_title"
      ]
    },
    "reviews_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/star.svg"
      },
      "children": []
    },
    "reviews_title": {
      "type": "Text",
      "props": {
        "text": "Guest Reviews & Reputation",
        "variant": "h3"
      },
      "children": []
    },
    "reviews_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "reviews_feedback",
        "reviews_service"
      ]
    },
    "reviews_feedback": {
      "type": "Text",
      "props": {
        "text": "Family Feedback: Prioritize reviews from other families with children of similar ages. Look for comments on cleanliness, staff friendliness, noise levels, and overall suitability for kids."
      },
      "children": []
    },
    "reviews_service": {
      "type": "Text",
      "props": {
        "text": "Service Quality: A hotel with attentive and helpful staff can significantly enhance your family's experience."
      },
      "children": []
    },
    "booking_flexibility_card": {
      "type": "Card",
      "props": {},
      "children": [
        "flexibility_header_stack",
        "flexibility_text_stack"
      ]
    },
    "flexibility_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "flexibility_icon",
        "flexibility_title"
      ]
    },
    "flexibility_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/calendar.svg"
      },
      "children": []
    },
    "flexibility_title": {
      "type": "Text",
      "props": {
        "text": "Booking Flexibility",
        "variant": "h3"
      },
      "children": []
    },
    "flexibility_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "flexibility_cancellation",
        "flexibility_channel"
      ]
    },
    "flexibility_cancellation": {
      "type": "Text",
      "props": {
        "text": "Cancellation Policy: Given the nature of family travel, understand the hotel's cancellation policy, especially for summer dates, to allow for unforeseen changes."
      },
      "children": []
    },
    "flexibility_channel": {
      "type": "Text",
      "props": {
        "text": "Booking Channel: Consider booking directly with the hotel for potentially better rates, loyalty points, and easier modifications, or use reputable travel agencies."
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "explore_hotels_button": {
      "type": "Button",
      "props": {
        "label": "Explore Orlando Hotels"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.visitorlando.com/places-to-stay/"
          }
        }
      },
      "children": []
    },
    "disney_guide_button": {
      "type": "Button",
      "props": {
        "label": "Disney World Planning Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.disneyworld.disney.go.com/plan/"
          }
        }
      },
      "children": []
    },
    "universal_info_button": {
      "type": "Button",
      "props": {
        "label": "Universal Orlando Resort Info"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.universalorlando.com/web/en/us"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "visitorlando_source_button": {
      "type": "Button",
      "props": {
        "label": "Orlando & Kissimmee Official Tourism",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.visitorlando.com/"
          }
        }
      },
      "children": []
    },
    "disneyworld_source_button": {
      "type": "Button",
      "props": {
        "label": "Walt Disney World Official Site",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.disneyworld.disney.go.com/"
          }
        }
      },
      "children": []
    },
    "universalorlando_source_button": {
      "type": "Button",
      "props": {
        "label": "Universal Orlando Resort Official Site",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.universalorlando.com/web/en/us"
          }
        }
      },
      "children": []
    }
  }
}
